class Solution:
    def mostVisited(self, n: int, rounds: List[int]) -> List[int]:
        cnt = [0] * (n + 1)
        cur = rounds[0]
        cnt[cur] += 1
        for nxt in rounds[1:]:
            while cur != nxt:
                cur = cur % n + 1
                cnt[cur] += 1
        mx = max(cnt)
        return [i for i in range(1, n + 1) if cnt[i] == mx]

