class Solution {
    public List<Integer> mostVisited(int n, int[] rounds) {
        int[] cnt = new int[n + 1];
        int cur = rounds[0];
        cnt[cur]++;
        for (int i = 1; i < rounds.length; i++) {
            while (cur != rounds[i]) {
                cur = cur % n + 1;
                cnt[cur]++;
            }
        }
        int mx = 0;
        for (int c : cnt) mx = Math.max(mx, c);
        List<Integer> res = new ArrayList<>();
        for (int i = 1; i <= n; i++)
            if (cnt[i] == mx) res.add(i);
        return res;
    }
}

