        while (cur !== rounds[i]) {
            cur = cur % n + 1;
            cnt[cur]++;
        }
    }
    const mx = Math.max(...cnt);
    const res = [];
    for (let i = 1; i <= n; i++)
        if (cnt[i] === mx) res.push(i);
    return res;
};

